import java.util.*;

public class Main {
    class FreqStack {
        List<Integer> values = new ArrayList<>();                        // every currently present value, in push order

        public void push(int val) {
            values.add(val);
        }

        public int pop() {
            Map<Integer, Integer> counts = new HashMap<>();
            for (int v : values) counts.merge(v, 1, Integer::sum);          // recompute every frequency from scratch
            int maxFreq = Collections.max(counts.values());
            for (int i = values.size() - 1; i >= 0; i--) {
                if (counts.get(values.get(i)) == maxFreq) {
                    return values.remove(i);                                    // remove the most recent value at max frequency
                }
            }
            return -1;
        }
    }

    public static void main(String[] args) {
        FreqStack freqStack = new FreqStack();
        for (int val : new int[]{5, 7, 5, 7, 4, 5}) freqStack.push(val);
        System.out.println(freqStack.pop());
        System.out.println(freqStack.pop());
        System.out.println(freqStack.pop());
        System.out.println(freqStack.pop());
    }
}

