#include <bits/stdc++.h>
using namespace std;

class FreqStack {
public:
    vector<int> values;                                                 // every currently present value, in push order

    void push(int val) {
        values.push_back(val);
    }

    int pop() {
        unordered_map<int, int> counts;
        for (int v : values) counts[v]++;                                   // recompute every frequency from scratch
        int maxFreq = 0;
        for (auto& entry : counts) maxFreq = max(maxFreq, entry.second);
        for (int i = (int)values.size() - 1; i >= 0; i--) {
            if (counts[values[i]] == maxFreq) {
                int result = values[i];
                values.erase(values.begin() + i);                               // remove the most recent value at max frequency
                return result;
            }
        }
        return -1;
    }
};

int main() {
    FreqStack freqStack;
    for (int val : {5, 7, 5, 7, 4, 5}) freqStack.push(val);
    cout << freqStack.pop() << endl;
    cout << freqStack.pop() << endl;
    cout << freqStack.pop() << endl;
    cout << freqStack.pop() << endl;
    return 0;
}

