class FreqStack:
    def __init__(self):
        self.freq = {}                                          # value to its current frequency
        self.group = {}                                            # frequency to the stack of values at that frequency
        self.max_freq = 0

    def push(self, val):
        f = self.freq.get(val, 0) + 1
        self.freq[val] = f
        if f not in self.group:
            self.group[f] = []
        self.group[f].append(val)                                    # this value just arrived at frequency f
        self.max_freq = max(self.max_freq, f)

    def pop(self):
        val = self.group[self.max_freq].pop()                        # most recent value at the current max frequency
        self.freq[val] -= 1
        if not self.group[self.max_freq]:
            self.max_freq -= 1                                          # this frequency group is now empty
        return val


