import java.util.*;

public class Main {
    class FreqStack {
        Map<Integer, Integer> freq = new HashMap<>();                        // value to its current frequency
        Map<Integer, Deque<Integer>> group = new HashMap<>();                  // frequency to the stack of values there
        int maxFreq = 0;

        public void push(int val) {
            int f = freq.getOrDefault(val, 0) + 1;
            freq.put(val, f);
            group.computeIfAbsent(f, k -> new ArrayDeque<>()).push(val);          // this value just arrived at frequency f
            maxFreq = Math.max(maxFreq, f);
        }

        public int pop() {
            int val = group.get(maxFreq).pop();                                  // most recent value at the current max frequency
            freq.put(val, freq.get(val) - 1);
            if (group.get(maxFreq).isEmpty()) {
                maxFreq--;                                                          // this frequency group is now empty
            }
            return val;
        }
    }

    public static void main(String[] args) {
        FreqStack freqStack = new FreqStack();
        for (int val : new int[]{5, 7, 5, 7, 4, 5}) freqStack.push(val);
        System.out.println(freqStack.pop());
        System.out.println(freqStack.pop());
        System.out.println(freqStack.pop());
        System.out.println(freqStack.pop());
    }
}

