#include <bits/stdc++.h>
using namespace std;

class FreqStack {
public:
    unordered_map<int, int> freq;                                           // value to its current frequency
    unordered_map<int, vector<int>> group;                                    // frequency to the stack of values there
    int maxFreq = 0;

    void push(int val) {
        int f = ++freq[val];
        group[f].push_back(val);                                               // this value just arrived at frequency f
        maxFreq = max(maxFreq, f);
    }

    int pop() {
        int val = group[maxFreq].back();
        group[maxFreq].pop_back();                                              // most recent value at the current max frequency
        freq[val]--;
        if (group[maxFreq].empty()) {
            maxFreq--;                                                            // this frequency group is now empty
        }
        return val;
    }
};

